-- Esquema Postgres de EntreLazados (Neon), traducido de esquema_mysql.sql
--
-- Primer paso de la migración (ver ROADMAP.md, Fase 1.2). La aplicación todavía
-- usa MySQL: este esquema sirve para probar Neon (npm run probar:neon) y como
-- base de la migración de las consultas.
--
-- Decisiones respecto a MySQL:
--   * Nombres en snake_case: Postgres pasa a minúsculas los nombres sin comillas
--     (UsuarioID volvería como "usuarioid"). El ORM mapeará a camelCase.
--   * AUTO_INCREMENT -> GENERATED BY DEFAULT AS IDENTITY (permite importar IDs).
--   * DATETIME -> timestamptz (guarda la zona horaria; DEFAULT now()).
--   * TINYINT(1) -> boolean.  TINYINT -> smallint.  LONGTEXT/TEXT -> text.
--   * ON UPDATE CURRENT_TIMESTAMP -> trigger.
--   * Índices en las llaves foráneas: InnoDB los crea solo, Postgres no.
--   * Extensión unaccent: para que buscar "latex" encuentre "Látex", como hacía
--     la collation de MySQL.
--
-- Uso: npm run db:esquema:neon   (usa la conexión directa DATABASE_URL_UNPOOLED)

CREATE EXTENSION IF NOT EXISTS unaccent;

CREATE TABLE departamentos (
    departamento_id     integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_departamento varchar(50) NOT NULL UNIQUE
);

CREATE TABLE usuarios (
    usuario_id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    correo_electronico      varchar(100) NOT NULL UNIQUE,
    contrasena_hash         varchar(255) NOT NULL,
    tipo_rol                varchar(20)  NOT NULL CHECK (tipo_rol IN ('Proveedor', 'Emprendedor', 'Administrador', 'Admin')),
    estado_cuenta           varchar(20)  DEFAULT 'Activo' CHECK (estado_cuenta IN ('Activo', 'Inactivo', 'Suspendido')),
    fecha_registro          timestamptz  DEFAULT now(),
    token_recuperacion      varchar(255),
    expiracion_token        timestamptz,
    -- Las cuentas nuevas empiezan en false si la verificación está activa (ver /registro)
    correo_verificado       boolean      NOT NULL DEFAULT true,
    token_verificacion      varchar(64),
    expiracion_verificacion timestamptz
);

CREATE TABLE perfiles_usuarios (
    perfil_id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id          integer NOT NULL UNIQUE REFERENCES usuarios (usuario_id) ON DELETE CASCADE,
    nombre_razon_social varchar(150) NOT NULL,
    telefono_whatsapp   varchar(20)  NOT NULL,
    departamento_id     integer NOT NULL REFERENCES departamentos (departamento_id),
    direccion_exacta    varchar(255),
    foto_perfil_url     varchar(255)
);
CREATE INDEX idx_perfiles_departamento ON perfiles_usuarios (departamento_id);

CREATE TABLE proveedores (
    proveedor_id                 integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id                   integer NOT NULL UNIQUE REFERENCES usuarios (usuario_id) ON DELETE CASCADE,
    numero_ruc                   varchar(50),
    nombre_comercial             varchar(150),
    descripcion_empresa          text,
    tipo_materia_prima_principal varchar(100)
);

CREATE TABLE emprendedores (
    emprendedor_id               integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id                   integer NOT NULL UNIQUE REFERENCES usuarios (usuario_id) ON DELETE CASCADE,
    nombre_marca                 varchar(150),
    especialidad_calzado         varchar(100),
    capacidad_produccion_mensual integer
);

CREATE TABLE administradores (
    admin_id     integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id   integer NOT NULL REFERENCES usuarios (usuario_id) ON DELETE CASCADE,
    nivel_acceso varchar(50) DEFAULT 'SuperAdmin'
);
CREATE INDEX idx_administradores_usuario ON administradores (usuario_id);

CREATE TABLE verificaciones_antifraude (
    verificacion_id      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id           integer NOT NULL UNIQUE REFERENCES usuarios (usuario_id) ON DELETE CASCADE,
    correo_confirmado    boolean DEFAULT true,
    cedula_ruc_subido    boolean DEFAULT false,
    ubicacion_confirmada boolean DEFAULT false,
    whatsapp_verificado  boolean DEFAULT false,
    foto_identidad_url   varchar(255),
    foto_selfie_url      varchar(255),
    estado_final         varchar(20) DEFAULT 'Pendiente' CHECK (estado_final IN ('Pendiente', 'Verificado', 'Rechazado')),
    fecha_actualizacion  timestamptz DEFAULT now()
);

-- Reemplazo de "ON UPDATE CURRENT_TIMESTAMP" de MySQL
CREATE FUNCTION actualizar_fecha_actualizacion() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.fecha_actualizacion := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_verificaciones_fecha_actualizacion
    BEFORE UPDATE ON verificaciones_antifraude
    FOR EACH ROW EXECUTE FUNCTION actualizar_fecha_actualizacion();

CREATE TABLE categorias_materiales (
    categoria_id     integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_categoria varchar(50) NOT NULL UNIQUE,
    descripcion      varchar(255)
);

CREATE TABLE ofertas (
    oferta_id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    proveedor_id          integer NOT NULL REFERENCES usuarios (usuario_id),
    titulo_material       varchar(150) NOT NULL,
    descripcion           varchar(1000),
    categoria_id          integer NOT NULL REFERENCES categorias_materiales (categoria_id),
    precio                numeric(10,2) NOT NULL,
    unidad_medida         varchar(30) NOT NULL,
    distancia_simulada_km integer NOT NULL,
    fecha_publicacion     timestamptz DEFAULT now(),
    fotos                 text
);
CREATE INDEX idx_ofertas_proveedor ON ofertas (proveedor_id);
CREATE INDEX idx_ofertas_categoria ON ofertas (categoria_id);

CREATE TABLE fotos_ofertas (
    foto_id      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    oferta_id    integer NOT NULL REFERENCES ofertas (oferta_id) ON DELETE CASCADE,
    foto_url     varchar(255) NOT NULL,
    es_principal boolean DEFAULT false,
    fecha_subida timestamptz DEFAULT now()
);
CREATE INDEX idx_fotos_ofertas_oferta ON fotos_ofertas (oferta_id);

CREATE TABLE subastas (
    subasta_id    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    proveedor_id  integer NOT NULL REFERENCES usuarios (usuario_id),
    -- Publicación de la que sale el lote (NULL si se creó sin publicación o si esta se borró)
    oferta_id     integer REFERENCES ofertas (oferta_id) ON DELETE SET NULL,
    categoria_id  integer REFERENCES categorias_materiales (categoria_id),
    titulo_lote   varchar(150) NOT NULL,
    precio_base   numeric(10,2) NOT NULL,
    precio_actual numeric(10,2) NOT NULL,
    fecha_inicio  timestamptz DEFAULT now(),
    fecha_fin     timestamptz NOT NULL,
    -- 'Cancelada': se borró la publicación mientras la subasta seguía abierta
    estado        varchar(15) DEFAULT 'Activa',
    CONSTRAINT chk_subastas_estado CHECK (estado IN ('Activa', 'Finalizada', 'Cancelada'))
);
-- El cierre de subastas busca las activas ya vencidas
CREATE INDEX idx_subastas_estado_fin ON subastas (estado, fecha_fin);
CREATE INDEX idx_subastas_proveedor ON subastas (proveedor_id);
CREATE INDEX idx_subastas_oferta ON subastas (oferta_id);
CREATE INDEX idx_subastas_categoria ON subastas (categoria_id);

CREATE TABLE pujas (
    puja_id        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    subasta_id     integer NOT NULL REFERENCES subastas (subasta_id) ON DELETE CASCADE,
    emprendedor_id integer NOT NULL REFERENCES usuarios (usuario_id),
    monto_puja     numeric(10,2) NOT NULL,
    fecha_puja     timestamptz DEFAULT now()
);
CREATE INDEX idx_pujas_subasta ON pujas (subasta_id);
CREATE INDEX idx_pujas_emprendedor ON pujas (emprendedor_id);

CREATE TABLE tratos_cerrados (
    trato_id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    proveedor_id        integer NOT NULL REFERENCES usuarios (usuario_id),
    emprendedor_id      integer NOT NULL REFERENCES usuarios (usuario_id),
    tipo_origen         varchar(20) NOT NULL CHECK (tipo_origen IN ('Oferta', 'Subasta', 'AcuerdoDirecto')),
    origen_id           integer,
    descripcion_resumen varchar(255) NOT NULL,
    monto_total         numeric(10,2) NOT NULL,
    estado_trato        varchar(20) DEFAULT 'Completado' CHECK (estado_trato IN ('Pendiente', 'EnProceso', 'Completado', 'Cancelado')),
    fecha_cierre        timestamptz DEFAULT now()
);
CREATE INDEX idx_tratos_proveedor ON tratos_cerrados (proveedor_id);
CREATE INDEX idx_tratos_emprendedor ON tratos_cerrados (emprendedor_id);

CREATE TABLE mensajes_chat (
    mensaje_id      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    remitente_id    integer NOT NULL REFERENCES usuarios (usuario_id),
    destinatario_id integer NOT NULL REFERENCES usuarios (usuario_id),
    contenido_texto text NOT NULL,
    fecha_envio     timestamptz DEFAULT now(),
    es_entregado    boolean DEFAULT false,
    fecha_entrega   timestamptz,
    es_leido        boolean DEFAULT false,
    fecha_lectura   timestamptz
);
-- Contador de mensajes no leídos
CREATE INDEX idx_mensajes_no_leidos ON mensajes_chat (destinatario_id, es_leido);
CREATE INDEX idx_mensajes_remitente ON mensajes_chat (remitente_id);

CREATE TABLE calificaciones (
    calificacion_id    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    trato_id           integer NOT NULL,
    autor_id           integer NOT NULL,
    calificado_id      integer NOT NULL,
    puntuacion         smallint NOT NULL,
    comentario         varchar(300),
    fecha_calificacion timestamptz DEFAULT now(),
    CONSTRAINT chk_calificaciones_puntuacion CHECK (puntuacion BETWEEN 1 AND 5),
    -- Una sola calificación por persona y trato
    CONSTRAINT uq_calificaciones_trato_autor UNIQUE (trato_id, autor_id),
    CONSTRAINT fk_calificaciones_trato FOREIGN KEY (trato_id) REFERENCES tratos_cerrados (trato_id) ON DELETE CASCADE,
    CONSTRAINT fk_calificaciones_autor FOREIGN KEY (autor_id) REFERENCES usuarios (usuario_id),
    CONSTRAINT fk_calificaciones_calificado FOREIGN KEY (calificado_id) REFERENCES usuarios (usuario_id)
);
CREATE INDEX idx_calificaciones_calificado ON calificaciones (calificado_id);
CREATE INDEX idx_calificaciones_autor ON calificaciones (autor_id);

CREATE TABLE notificaciones (
    notificacion_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id      integer NOT NULL,
    -- PujaSuperada, PujaRecibida, SubastaGanada, SubastaTerminada, SubastaCancelada,
    -- TratoActualizado, CalificacionRecibida, AlertaBusqueda, FavoritoRebajado
    tipo            varchar(30)  NOT NULL,
    titulo          varchar(120) NOT NULL,
    mensaje         varchar(300) NOT NULL,
    enlace          varchar(200),          -- página a la que lleva al hacer clic (p. ej. mercado.html)
    referencia_id   integer,               -- subasta_id o trato_id, para no repetir avisos
    es_leida        boolean NOT NULL DEFAULT false,
    fecha_creacion  timestamptz DEFAULT now(),
    CONSTRAINT fk_notificaciones_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios (usuario_id) ON DELETE CASCADE
);
CREATE INDEX idx_notificaciones_usuario ON notificaciones (usuario_id, es_leida, fecha_creacion);

CREATE TABLE favoritos (
    usuario_id     integer NOT NULL,
    oferta_id      integer NOT NULL,
    fecha_guardado timestamptz DEFAULT now(),
    PRIMARY KEY (usuario_id, oferta_id),
    CONSTRAINT fk_favoritos_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios (usuario_id) ON DELETE CASCADE,
    CONSTRAINT fk_favoritos_oferta FOREIGN KEY (oferta_id) REFERENCES ofertas (oferta_id) ON DELETE CASCADE
);
CREATE INDEX idx_favoritos_oferta ON favoritos (oferta_id);

CREATE TABLE alertas_busqueda (
    alerta_id      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id     integer NOT NULL,
    palabra_clave  varchar(60),
    categoria_id   integer,
    precio_maximo  numeric(10,2),
    fecha_creacion timestamptz DEFAULT now(),
    CONSTRAINT fk_alertas_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios (usuario_id) ON DELETE CASCADE,
    CONSTRAINT fk_alertas_categoria FOREIGN KEY (categoria_id) REFERENCES categorias_materiales (categoria_id) ON DELETE CASCADE
);
CREATE INDEX idx_alertas_usuario ON alertas_busqueda (usuario_id);
CREATE INDEX idx_alertas_categoria ON alertas_busqueda (categoria_id);

